    def run(_job), do: :ok
  end

  test "resource error mappings name real constraints and indexes" do
    constraints =
      SQL.query!(Repo, """
      SELECT relation.relname, constraint_row.conname, constraint_row.contype::text, referenced.relname
      FROM pg_constraint constraint_row
      JOIN pg_class relation ON relation.oid = constraint_row.conrelid
      JOIN pg_namespace namespace ON namespace.oid = relation.relnamespace
      LEFT JOIN pg_class referenced ON referenced.oid = constraint_row.confrelid
      WHERE namespace.nspname = current_schema()
      """).rows
      |> MapSet.new()

    indexes =
      SQL.query!(Repo, """
      SELECT tablename, indexname FROM pg_indexes WHERE schemaname = current_schema()
      """).rows
      |> MapSet.new()

    for schema <- schemas(), Spark.Dsl.is?(schema, Ash.Resource) do
      table = schema.__schema__(:source)

      for constraint <- AshPostgres.DataLayer.Info.check_constraints(schema) do
        assert MapSet.member?(constraints, [table, constraint.name, "c", nil]),
               "#{inspect(schema)} maps a missing check constraint #{constraint.name}"
      end

      for {_fields, name} <- AshPostgres.DataLayer.Info.foreign_key_names(schema) do
        assert Enum.any?(constraints, fn
                 [child, ^name, "f", parent] -> table in [child, parent]
                 _constraint -> false
               end),
               "#{inspect(schema)} maps a missing foreign key #{name}"
      end

      for {_fields, name} <- AshPostgres.DataLayer.Info.unique_index_names(schema) do
        assert MapSet.member?(indexes, [table, name]),
               "#{inspect(schema)} maps a missing unique index #{name}"
      end
    end
  end

  test "Ash identities use the existing index and its exact tenant scope" do
    for schema <- schemas(),
        Spark.Dsl.is?(schema, Ash.Resource),
        identity <- Ash.Resource.Info.identities(schema) do
      table = schema.__schema__(:source)
      index = AshPostgres.DataLayer.Info.identity_index_names(schema)[identity.name]
      assert is_binary(index), "#{inspect(schema)}.#{identity.name} needs its existing index name"

      rows =
        SQL.query!(
          Repo,
          """
          SELECT COALESCE(attribute.attname, pg_get_indexdef(index_info.indexrelid, key.position::int, true))
          FROM pg_index index_info
          JOIN pg_class index_table ON index_table.oid = index_info.indexrelid
          JOIN pg_class source_table ON source_table.oid = index_info.indrelid
          JOIN unnest(index_info.indkey) WITH ORDINALITY AS key(attnum, position) ON true
          LEFT JOIN pg_attribute attribute ON attribute.attrelid = source_table.oid AND attribute.attnum = key.attnum
          WHERE source_table.relname = $1 AND index_table.relname = $2 AND index_info.indisunique
          ORDER BY key.position
          """,
          [table, index]
        ).rows
        |> List.flatten()

      assert rows != [], "#{inspect(schema)}.#{identity.name} has no matching unique index"

      expected =
        Enum.map(identity.keys, fn key ->
          case Ash.Resource.Info.attribute(schema, key) do
            nil ->
              assert Ash.Resource.Info.calculation(schema, key)
              sql = AshPostgres.DataLayer.Info.calculations_to_sql(schema)[key]
              assert is_binary(sql), "#{inspect(schema)}.#{key} needs its exact index expression"
              index_expression!(table, sql)

            _attribute ->
              to_string(key)
          end
        end)

      if sql = AshPostgres.DataLayer.Info.identity_wheres_to_sql(schema)[identity.name] do
        [[predicate]] =
          SQL.query!(
            Repo,
            "SELECT pg_get_expr(index_info.indpred, index_info.indrelid) FROM pg_index index_info JOIN pg_class index_table ON index_table.oid = index_info.indexrelid WHERE index_table.relname = $1",
            [index]
          ).rows

        assert index_expression!(table, predicate) == index_expression!(table, sql)
      end

      expected =
        case schema.__tenancy__() do
          :site ->
            expected

          :tenant ->
            assert identity.all_tenants? == "tenant_id" not in rows
            if identity.all_tenants?, do: assert(Map.has_key?(@global_unique_indexes, index))
            if identity.all_tenants?, do: expected, else: ["tenant_id" | expected]
        end

      assert MapSet.new(rows) == MapSet.new(expected)
    end
  end

  defp index_expression!(table, expression) do
    [[[%{"Plan" => %{"Output" => [canonical]}}]]] =
      SQL.query!(
        Repo,
        ~s|EXPLAIN (VERBOSE, FORMAT JSON, COSTS OFF) SELECT #{expression} FROM "#{table}"|,
        []
      ).rows

    canonical
  end

  test "every table has an explicit site declaration or a required tenant foreign key" do
    schemas = schemas()

    declared_site =
      for schema <- schemas, schema.__tenancy__() == :site, do: schema.__schema__(:source)

    assert MapSet.new(declared_site ++ ["oban_jobs", "oban_peers", "schema_migrations"]) ==
             MapSet.new(@site_tables)

    site_tables = MapSet.new(@site_tables)

    rows =
      SQL.query!(Repo, """
        SELECT tables.table_name, columns.data_type, columns.is_nullable,
          EXISTS (
            SELECT 1 FROM pg_constraint c
            JOIN pg_attribute a ON a.attrelid = c.conrelid AND a.attnum = ANY(c.conkey)
            WHERE c.contype = 'f' AND c.conrelid = (quote_ident(tables.table_schema) || '.' || quote_ident(tables.table_name))::regclass
              AND c.confrelid = 'tenants'::regclass AND a.attname = 'tenant_id' AND c.confdeltype = 'r'
          )
        FROM information_schema.tables tables
        LEFT JOIN information_schema.columns columns
          ON columns.table_schema = tables.table_schema AND columns.table_name = tables.table_name AND columns.column_name = 'tenant_id'
        WHERE tables.table_schema = current_schema() AND tables.table_type = 'BASE TABLE'
        ORDER BY tables.table_name
      """).rows

    for [table, type, nullable, foreign_key] <- rows, not MapSet.member?(site_tables, table) do
      assert {type, nullable, foreign_key} == {"uuid", "NO", true},
             "#{table} has no required tenant ownership"
    end

    for schema <- schemas do
      [row] = Enum.filter(rows, &(hd(&1) == schema.__schema__(:source)))

      if schema.__tenancy__() == :tenant do
        assert schema.__schema__(:type, :tenant_id) == Ankole.Ecto.UUIDv7
        assert Enum.at(row, 2) == "NO"
      else
        assert MapSet.member?(site_tables, hd(row))
      end
    end
  end

  test "every tenant-to-tenant foreign key binds the same tenant" do
    tenant_tables =
      for schema <- schemas(), schema.__tenancy__() == :tenant, do: schema.__schema__(:source)

    assert tenant_tables != []

    assert %{rows: []} =
             SQL.query!(
               Repo,
               """
               SELECT child.relname, parent.relname, foreign_key.conname
               FROM pg_constraint foreign_key
               JOIN pg_class child ON child.oid = foreign_key.conrelid
               JOIN pg_class parent ON parent.oid = foreign_key.confrelid
               JOIN pg_namespace namespace ON namespace.oid = child.relnamespace
               JOIN pg_attribute child_tenant ON child_tenant.attrelid = child.oid
                 AND child_tenant.attname = 'tenant_id' AND NOT child_tenant.attisdropped
               JOIN pg_attribute parent_tenant ON parent_tenant.attrelid = parent.oid
                 AND parent_tenant.attname = 'tenant_id' AND NOT parent_tenant.attisdropped
               WHERE foreign_key.contype = 'f' AND namespace.nspname = current_schema()
                 AND child.relname = ANY($1) AND parent.relname = ANY($1)
                 AND NOT EXISTS (
                   SELECT 1
                   FROM unnest(foreign_key.conkey, foreign_key.confkey) AS key(child, parent)
                   WHERE key.child = child_tenant.attnum AND key.parent = parent_tenant.attnum
                 )
               ORDER BY child.relname, foreign_key.conname
               """,
               [tenant_tables]
             )
  end

  test "tenant deletion covers every table with tenant ownership" do
    tables =
      SQL.query!(
        Repo,
        "SELECT table_name FROM information_schema.columns WHERE table_schema = current_schema() AND column_name = 'tenant_id'"
      ).rows
      |> List.flatten()

    assert MapSet.new(Ankole.Tenants.Jobs.Delete.tenant_tables()) == MapSet.new(tables)
  end

  test "every tenant unique key includes tenant_id or has a documented global identity" do
    tenant_tables =
      for schema <- schemas(), schema.__tenancy__() == :tenant, do: schema.__schema__(:source)

    rows =
      SQL.query!(Repo, """
        SELECT table_class.relname, index_class.relname,
          EXISTS (
            SELECT 1 FROM pg_attribute column_row
            WHERE column_row.attrelid = table_class.oid AND column_row.attname = 'tenant_id'
              AND column_row.attnum = ANY(index_row.indkey)
          )
        FROM pg_index index_row
        JOIN pg_class table_class ON table_class.oid = index_row.indrelid
        JOIN pg_class index_class ON index_class.oid = index_row.indexrelid
        WHERE index_row.indisunique AND table_class.relnamespace = current_schema()::regnamespace
      """).rows

    unscoped = for [table, name, false] <- rows, table in tenant_tables, do: name

    for name <- unscoped do
      assert Map.has_key?(@global_unique_indexes, name),
             "#{name} has no tenant key or reviewed global identity"
    end

    assert MapSet.new(unscoped) == MapSet.new(Map.keys(@global_unique_indexes))
  end

  test "durable authorization keeps the historical human UID without owning the human row" do
    work_schemas =
      Enum.filter(schemas(), fn schema ->
        Enum.all?(
          [:authorization_kind, :human_uid, :human_access_version],
          &(&1 in schema.__schema__(:fields))
        )
      end)

    assert work_schemas != []

    for schema <- work_schemas do
      table = schema.__schema__(:source)

      assert [["text", false]] =
               SQL.query!(
                 Repo,
                 """
                   SELECT columns.data_type, EXISTS (
                     SELECT 1 FROM pg_constraint constraint_row
                     JOIN pg_attribute column_row
                       ON column_row.attrelid = constraint_row.conrelid
                         AND column_row.attnum = ANY(constraint_row.conkey)
                     WHERE constraint_row.contype = 'f'
                       AND constraint_row.conrelid = $1::text::regclass
                       AND column_row.attname = 'human_uid'
                   )
                   FROM information_schema.columns columns
                   WHERE columns.table_schema = current_schema()
                     AND columns.table_name = $1 AND columns.column_name = 'human_uid'
                 """,
                 [table]
               ).rows
    end
  end

  test "every Oban worker declares its execution scope" do
    for module <- Ankole.TestModules.all(),
        Code.ensure_loaded?(module),
        function_exported?(module, :__opts__, 0) do
      assert function_exported?(module, :__tenancy__, 0), "#{inspect(module)} must use Ankole.Job"
      assert module.__tenancy__() in [:site, :tenant]
    end
  end

  test "query escape hatches stay in reviewed functions with reviewed call counts" do
    calls =
      for file <- source_files(),
          ast = file |> File.read!() |> Code.string_to_quoted!(),
          call <- query_escapes(ast, file),
          do: call

    actual = Enum.frequencies(calls)

    changes =
      for key <- Enum.uniq(Map.keys(actual) ++ Map.keys(@reviewed_query_escapes)),
          actual[key] != @reviewed_query_escapes[key],
          do: {key, @reviewed_query_escapes[key], actual[key]}

    assert actual == @reviewed_query_escapes,
           "Review query escapes at their domain owner: #{inspect(changes)}"
  end

  test "Database peer elects a leader and cron inserts without a tenant" do
    name = Module.concat(__MODULE__, DatabasePeer)

    Repo.without_tenant(fn ->
      start_supervised!(
        {Oban,
         name: name,
         repo: Repo,
         testing: :disabled,
         peer: Oban.Peers.Database,
         notifier: Oban.Notifiers.PG,
         queues: [],
         cron: [crontab: [{"* * * * *", CronProbe}]]}
      )

      assert Oban.Peer.leader?(name)
      cron = Oban.Registry.whereis(name, {:plugin, Oban.Cron})
      assert is_pid(cron)
      send(cron, :evaluate)
      :sys.get_state(cron)

      assert Repo.exists?(
               from(job in Oban.Job, where: job.worker == ^Oban.Worker.to_string(CronProbe))
             )

      assert %{success: 1, failure: 0} =
               Oban.drain_queue(name, queue: :tenancy_guard, with_safety: false)
    end)
  end

  defp source_files,
    do:
      Path.wildcard("lib/**/*.ex") ++
        Path.wildcard("../control_plane_core/lib/**/*.ex") ++
        Path.wildcard("../../plugins/**/lib/**/*.ex")

  defp query_escapes(ast, file) do
    {_ast, calls} =
      Macro.prewalk(ast, [], fn
        {definition, _, [head, body]} = node, calls
        when definition in [:def, :defp, :defmacro, :defmacrop] ->
          name = function_name(head)

          {_body, found} =
            Macro.prewalk(body, [], fn node, found ->
              case query_escape_kind(node) do
                nil -> {node, found}
                kind -> {node, ["#{kind}:#{file}:#{name}" | found]}
              end
            end)

          {node, found ++ calls}

        node, calls ->
          {node, calls}
      end)

    calls
  end

  defp function_name({:when, _, [head | _]}), do: function_name(head)
  defp function_name({name, _, _args}), do: name

  defp query_escape_kind({{:., _, [_module, :across_tenants]}, _, args}) when is_list(args),
    do: :across_tenants

  defp query_escape_kind({{:., _, [module, call]}, _, args})
       when call in [:query, :query!, :query_many, :query_many!] and is_list(args) do
    if Macro.to_string(module) in [
         "SQL",
         "Ecto.Adapters.SQL",
         "Repo",
         "repo",
         "Ankole.Repo",
         "Postgrex"
       ],
       do: :raw_sql
  end

  defp query_escape_kind({{:., _, [module, :stream]}, _, args}) when is_list(args) do
    if Macro.to_string(module) in ["SQL", "Ecto.Adapters.SQL", "Postgrex"], do: :raw_sql
  end

  defp query_escape_kind({{:., _, [_module, :fragment]}, meta, args}),
    do: query_escape_kind({:fragment, meta, args})

  defp query_escape_kind({:fragment, _, [sql | _args]}) when is_binary(sql) do
    if Regex.match?(~r/\b(?:SELECT|INSERT|UPDATE|DELETE)\b/i, sql), do: :sql_fragment
  end

  defp query_escape_kind(_node), do: nil

  # A polymorphic resource (an operations container) has no table.
  defp schemas do
    for module <- Ankole.TestModules.all(),
        Code.ensure_loaded?(module),
        function_exported?(module, :__schema__, 1),
        module.__schema__(:source) not in [nil, ""] do
      assert function_exported?(module, :__tenancy__, 0),
             "#{inspect(module)} must declare its ownership through Ankole.Ash.Resource or Ankole.Schema"

      module
    end
  end
end
